import numpy as np


def r2_out_of_sample(y, pred):
    y = np.asarray(y, dtype=float)
    pred = np.asarray(pred, dtype=float)
    return float(1 - np.sum((y - pred) ** 2) / np.sum((y - y.mean()) ** 2))


def r2_from_days(mse, var_y):
    return float(np.mean(1 - np.asarray(mse) / np.asarray(var_y)))
